package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.ErrorCode;
import com.ruoyi.medical.workflow.*;
import com.ruoyi.medical.workflow.TaskRunStageProtocolV2.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.ruoyi.medical.persistence.TaskRunActivityJournal.*;

/** Actual deterministic result COMMIT. This never manufactures artifact outputs,
 * human waiting work, professional approval, or a later-stage success. */
public final class TaskRunStageCommitServiceV2 {
    static final String ACTION="task.run.stage.committed.v2";
    private static final Contract CONTRACT=contract();static final String MANIFEST=CONTRACT.manifest();
    private final JdbcTemplate db;private final PermissionSchema json;private final TaskRunActivityJournal journal;
    private final TaskStrictFieldCompletionAuthority results;private final TaskRunGraphService graphs;private final TaskRunWorkflowProtocolBinding protocols;
    private final JsonMapper reader=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).build();
    public TaskRunStageCommitServiceV2(DataSource data,PermissionSchema json,TaskStrictFieldCompletionAuthority results,TaskRunGraphService graphs,TaskRunWorkflowProtocolBinding protocols){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.results=results;this.graphs=graphs;this.protocols=protocols;journal=new TaskRunActivityJournal(db,json);}
    StageCommitV2 commit(FormalTaskNodeAuthority.Verified node,WorkflowProtocol.Reference ref,FieldCompletionV2 c)throws Exception{
        node.requireUnchanged();c.require(ref,"N03",c.commandId());var a=node.controlAdmission();var input=node.currentStrictFieldInput();same(ref.tenantId(),input.input().tenantId());same(ref.projectId(),input.input().projectId());same(c.runId(),input.input().runId());same(c.stepId(),input.input().stepId());same(c.inputId(),input.inputId());same(c.inputSha256(),input.inputSha256());
        var graph=graphs.require(a,ref.runId());if(!graph.requiredStages().contains(c.stageKind()))bad();same(graph.graphSha256(),input.graphSha256());var protocol=protocols.requireWaitingV2(a,ref.runId());
        var produced=results.requireProduced(node,c.resultId());produced.requireUnchanged();check(c,produced.runId(),produced.stepId(),produced.inputId(),produced.inputSha256(),produced.actionId(),produced.leaseGeneration(),produced.resultId(),produced.resultSha256(),produced.receiptSha256());
        boolean satisfied;try{produced.requireStageSatisfied();satisfied=true;}catch(TenantAccessException failure){if(failure.code()!=ErrorCode.STEP_NOT_READY)throw failure;satisfied=false;}
        var row=step(a,ref,c.stepId());same("RUNNING",text(row,"status"));same(c.inputSha256(),text(row,"input_sha256"));same(Long.toString(c.leaseGeneration()),number(row,"lease_generation"));if(row.get("lease_owner")==null||row.get("lease_expires_at")==null)bad();
        var existing=find(a,ref);if(existing.stream().anyMatch(v->v.required("body").required("completion").required("stageKind").asText().equals(c.stageKind())))bad();
        String obligation=obligation(ref,graph.graphId(),graph.graphSha256(),c.stageKind());var body=body(ref,c,graph.graphId(),graph.graphSha256(),obligation,satisfied,protocol.protocolSha256(),produced.receipt());String id=derived(c.commandId(),ACTION);var receipt=new StageCommitV2("2.0.0",c.stageKind(),obligation,graph.graphId(),graph.graphSha256(),c,satisfied?"SATISFIED":"BLOCKED",id,journal.hash(body));var witness=witness(body,receipt);
        produced.requireUnchanged();if(satisfied)produced.requireStageSatisfied();node.requireUnchanged();graph.requireUnchanged();protocol.requireUnchanged();
        journal.write(a,ref.projectId(),ref.runId(),id,ACTION,key(c),c.commandId(),journal.hash(reader.valueToTree(c)),classification(a,ref),"2.0.0",MANIFEST,witness);
        changed(db.update("UPDATE run_step SET status=?,output_ref='[]',revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND status='RUNNING' AND revision=? AND input_sha256=? AND lease_generation=? AND lease_owner=? AND lease_expires_at>UTC_TIMESTAMP(6)",satisfied?"SUCCEEDED":"WAITING_INPUT",ref.tenantId(),ref.projectId(),ref.runId(),c.stepId(),number(row,"revision"),c.inputSha256(),c.leaseGeneration(),text(row,"lease_owner")));return receipt;
    }
    Optional<StageCommitV2> recover(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,FieldCompletionV2 c)throws Exception{
        recovery(a,ref);var value=journal.read(a,ref.projectId(),ref.runId(),derived(c.commandId(),ACTION),ACTION,key(c),c.commandId(),journal.hash(reader.valueToTree(c)),classification(a,ref),"2.0.0",MANIFEST);if(value.isEmpty())return Optional.empty();var result=read(value.get());same(c,result.completion());
        var original=results.requireOriginal(a,c);original.requireUnchanged();same(c.producerReceiptSha256(),original.receiptSha256());same(c.resultSha256(),original.resultSha256());same(original.stageSatisfied(),result.satisfied());
        var graph=graphs.requireOriginal(a,ref.runId());var protocol=protocols.requireWaitingV2(a,ref.runId());var expected=body(ref,c,graph.graphId(),graph.graphSha256(),obligation(ref,graph.graphId(),graph.graphSha256(),c.stageKind()),result.satisfied(),protocol.protocolSha256(),original.receipt());same(json.canonical(expected),json.canonical(value.get().required("body")));verifyStep(a,ref,result);original.requireUnchanged();graph.requireUnchanged();protocol.requireUnchanged();return Optional.of(result);
    }
    List<StageCommitV2> load(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref)throws Exception{recovery(a,ref);var result=new ArrayList<StageCommitV2>();for(var value:find(a,ref)){var c=reader.treeToValue(value.required("body").required("completion"),FieldCompletionV2.class);result.add(recover(a,ref,c).orElseThrow());}return List.copyOf(result);}
    /** A committed stage journal is the factual boundary for lifecycle use; this
     * reader cannot create it or authorize the original computation. */
    List<StageCommitV2> loadLifecycle(TaskRunLifecycleAuthority.Proof p)throws Exception{
        p.require(p.operation());var a=p.admission();var ref=p.reference();var result=new ArrayList<StageCommitV2>();for(var value:find(a,ref)){var r=read(value);var c=r.completion();var saved=journal.read(a,ref.projectId(),ref.runId(),r.receiptId(),ACTION,key(c),c.commandId(),journal.hash(reader.valueToTree(c)),p.classification(),"2.0.0",MANIFEST).orElseThrow();same(json.canonical(value),json.canonical(saved));var original=results.requireLifecycleOriginal(p,c);original.requireUnchanged();same(original.stageSatisfied(),r.satisfied());same(json.canonical(original.receipt()),json.canonical(saved.required("body").required("producer_receipt")));same(json.canonical(reader.valueToTree(ref)),json.canonical(saved.required("body").required("reference")));var protocol=protocols.requireWaitingV2(a,ref.runId());same(protocol.protocolSha256(),saved.required("body").required("protocol_sha256").asText());protocol.requireUnchanged();same(p.graph().graphId(),r.graphId());same(p.graph().graphSha256(),r.graphSha256());same(obligation(ref,r.graphId(),r.graphSha256(),c.stageKind()),r.obligationSha256());if(!p.graph().requiredStages().contains(c.stageKind()))bad();verifyStep(a,ref,r);result.add(r);}p.require(p.operation());return List.copyOf(result);
    }
    /** Current downstream producer + original immutable N03 COMMIT. No old lease
     * is revived and no ordinary Admission can mint this proof. */
    public ForConsumer requireForConsumer(TaskNodeProductionAuthority.Verified production,FieldCompletionV2 completion)throws Exception{
        return new ForConsumer(production,completion,consumer(production,completion,null),null);
    }
    public ForConsumer requireForConsumer(TaskRunResumeOriginalAuthority.Source source,FieldCompletionV2 completion)throws Exception{
        source.requireOriginal(source.admission(),completion.runId(),completion.stepId());return new ForConsumer(source.successor(),completion,consumer(source.successor(),completion,source),source);
    }
    public final class ForConsumer{
        private final TaskRunResumeOriginalAuthority.Source source;private final TaskNodeProductionAuthority.Verified production;private final FieldCompletionV2 completion;private final StageCommitV2 receipt;private final Thread thread=Thread.currentThread();private final TenantScope scope=TenantScope.requireCurrent();private final Map<Object,Object> resources=Map.copyOf(org.springframework.transaction.support.TransactionSynchronizationManager.getResourceMap());private boolean ended;
        private ForConsumer(TaskNodeProductionAuthority.Verified p,FieldCompletionV2 c,StageCommitV2 r,TaskRunResumeOriginalAuthority.Source source){this.source=source;production=p;completion=c;receipt=r;if(resources.isEmpty()||!org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())bad();org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCompletion(int status){ended=true;}});}
        public void requireUnchanged()throws Exception{var current=org.springframework.transaction.support.TransactionSynchronizationManager.getResourceMap();if(ended||thread!=Thread.currentThread()||scope!=TenantScope.requireCurrent()||!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||resources.size()!=current.size()||resources.entrySet().stream().anyMatch(e->current.get(e.getKey())!=e.getValue()))bad();production.requireUnchanged();same(receipt,consumer(production,completion,source));}
        public StageCommitV2 receipt(){return receipt;}public FieldCompletionV2 completion(){return completion;}
    }
    private StageCommitV2 consumer(TaskNodeProductionAuthority.Verified production,FieldCompletionV2 c,TaskRunResumeOriginalAuthority.Source source)throws Exception{
        production.requireUnchanged();if(source==null)same(production.runId(),c.runId());else source.requireOriginal(production.admission(),c.runId(),c.stepId());var a=production.admission();var protocol=protocols.requireWaitingV2(a,c.runId());
        var launch=one(db.queryForList("SELECT reference_json FROM task_run_workflow_launch WHERE tenant_id=? AND project_id=? AND run_id=? LIMIT 2 FOR UPDATE",production.tenantId(),production.projectId(),c.runId()));
        var ref=JsonMapper.builder().propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).build().treeToValue(reader.readTree(text(launch,"reference_json")),WorkflowProtocol.Reference.class);same(production.tenantId(),ref.tenantId());same(production.projectId(),ref.projectId());c.require(ref,"N03",c.commandId());
        var value=journal.read(a,ref.projectId(),ref.runId(),derived(c.commandId(),ACTION),ACTION,key(c),c.commandId(),journal.hash(reader.valueToTree(c)),production.classification(),"2.0.0",MANIFEST).orElseThrow(()->new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE));var r=read(value);same(c,r.completion());
        var original=source==null?results.requireConsumerOriginal(production,c):results.requireConsumerOriginal(source,c);original.requireUnchanged();same(original.stageSatisfied(),r.satisfied());
        if(source!=null){var graph=graphs.requireOriginal(source);if(!graph.requiredStages().contains(c.stageKind()))bad();same(json.canonical(body(ref,c,graph.graphId(),graph.graphSha256(),obligation(ref,graph.graphId(),graph.graphSha256(),c.stageKind()),r.satisfied(),protocol.protocolSha256(),original.receipt())),json.canonical(value.required("body")));verifyStep(a,ref,r);original.requireUnchanged();graph.requireUnchanged();protocol.requireUnchanged();source.requireUnchanged();return r;}
        var graph=graphs.require(a,ref.runId());if(!graph.requiredStages().contains(c.stageKind()))bad();
        same(json.canonical(body(ref,c,graph.graphId(),graph.graphSha256(),obligation(ref,graph.graphId(),graph.graphSha256(),c.stageKind()),r.satisfied(),protocol.protocolSha256(),original.receipt())),json.canonical(value.required("body")));verifyStep(a,ref,r);original.requireUnchanged();graph.requireUnchanged();protocol.requireUnchanged();production.requireUnchanged();return r;
    }
    private List<JsonNode> find(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref)throws Exception{var rows=db.queryForList("SELECT response_ref FROM operation_record WHERE tenant_id=? AND subject_id=? AND target_id=? AND operation_name=? ORDER BY operation_id LIMIT 5 FOR UPDATE",ref.tenantId(),a.actorId(),ref.runId(),ACTION);if(rows.size()>4)bad();var values=new ArrayList<JsonNode>();for(var row:rows)values.add(reader.readTree(text(row,"response_ref")));return values;}
    private StageCommitV2 read(JsonNode value)throws Exception{if(!CONTRACT.schema().validate(value).isEmpty())bad();var r=reader.treeToValue(value.required("receipt"),StageCommitV2.class);same(derived(r.completion().commandId(),ACTION),r.receiptId());same(journal.hash(value.required("body")),r.receiptSha256());var body=value.required("body");same(json.canonical(reader.valueToTree(r.completion())),json.canonical(body.required("completion")));same(r.graphId(),body.required("graph_id").asText());same(r.graphSha256(),body.required("graph_sha256").asText());same(r.obligationSha256(),body.required("obligation_sha256").asText());same(r.disposition(),body.required("disposition").asText());var producer=body.required("producer_receipt");var c=r.completion();same(c.producerReceiptSha256(),journal.hash(producer));same(c.resultId(),producer.required("result_id").asText());same(c.resultSha256(),producer.required("result_sha256").asText());same(c.inputId(),producer.required("input_id").asText());same(c.inputSha256(),producer.required("input_sha256").asText());same(c.actionId(),producer.required("action_id").asText());same(Long.toString(c.leaseGeneration()),producer.required("lease_generation").asText());return r;}
    private JsonNode body(WorkflowProtocol.Reference ref,FieldCompletionV2 c,String graph,String hash,String obligation,boolean satisfied,String protocol,JsonNode original){var n=json.object().put("schema_version","2.0.0").put("kind","TASK_TYPED_STAGE_COMMIT").put("graph_id",graph).put("graph_sha256",hash).put("obligation_sha256",obligation).put("protocol_sha256",protocol).put("disposition",satisfied?"SATISFIED":"BLOCKED");n.set("reference",reader.valueToTree(ref));n.set("completion",reader.valueToTree(c));n.set("producer_receipt",original);return n;}
    private JsonNode witness(JsonNode body,StageCommitV2 r){var n=json.object();n.set("body",body);n.set("receipt",reader.valueToTree(r));if(!CONTRACT.schema().validate(n).isEmpty())bad();return n;}
    private void verifyStep(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,StageCommitV2 r)throws Exception{var c=r.completion();var row=step(a,ref,c.stepId());same(r.satisfied()?"SUCCEEDED":"WAITING_INPUT",text(row,"status"));same(c.inputSha256(),text(row,"input_sha256"));same(Long.toString(c.leaseGeneration()),number(row,"lease_generation"));same(json.tree(List.of()),reader.readTree(text(row,"output_ref")));}
    private Map<String,Object> step(EnterpriseAccess.Admission a,WorkflowProtocol.Reference r,String step){return one(db.queryForList("SELECT * FROM run_step WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",r.tenantId(),r.projectId(),r.runId(),step));}
    private String classification(EnterpriseAccess.Admission a,WorkflowProtocol.Reference r){return one(db.query("SELECT classification FROM task_run WHERE tenant_id=? AND project_id=? AND run_id=? AND created_by=? LIMIT 2 FOR UPDATE",(rs,n)->rs.getString(1),r.tenantId(),r.projectId(),r.runId(),a.actorId()));}
    String obligation(WorkflowProtocol.Reference r,String graph,String hash,String stage)throws Exception{var n=json.object().put("schema_version","1.0.0").put("kind","TASK_REQUIRED_STAGE").put("tenant_id",r.tenantId()).put("project_id",r.projectId()).put("run_id",r.runId()).put("graph_id",graph).put("graph_sha256",hash).put("stage_kind",stage);return journal.hash(n);}
    private static void check(FieldCompletionV2 c,String run,String step,String input,String hash,String action,long generation,String result,String resultHash,String receiptHash){same(c.runId(),run);same(c.stepId(),step);same(c.inputId(),input);same(c.inputSha256(),hash);same(c.actionId(),action);same(c.leaseGeneration(),generation);same(c.resultId(),result);same(c.resultSha256(),resultHash);same(c.producerReceiptSha256(),receiptHash);}
    private static String key(FieldCompletionV2 c){return "task-stage-v2:"+c.runId()+":"+c.stageKind();}
    private static void recovery(EnterpriseAccess.Admission a,WorkflowProtocol.Reference r){if(!a.recoveryWorker())throw new TenantAccessException(ErrorCode.ACCESS_DENIED);a.recoveryProof().requireActive();same(r.runId(),a.recoveryProof().identity().runId());same(r.tenantId(),a.context().tenant_id());same(r.projectId(),a.recoveryProof().identity().projectId());}
    private record Contract(String manifest,com.networknt.schema.JsonSchema schema){}
    private static Contract contract(){try(var in=Objects.requireNonNull(TaskRunStageCommitServiceV2.class.getResourceAsStream("/task-run-stage-commit-v2.schema.json"))){byte[] bytes=in.readAllBytes();var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(new JsonMapper().readTree(bytes),com.networknt.schema.SchemaValidatorsConfig.builder().formatAssertionsEnabled(true).build());schema.initializeValidators();return new Contract(org.apache.commons.codec.digest.DigestUtils.sha256Hex(bytes),schema);}catch(java.io.IOException e){throw new IllegalStateException(e);}}
}
